#!/system/bin/sh
# ═══════════════════════════════════════════════════════
#   DEVINE Protected Script (Auto-Decrypt)
# ═══════════════════════════════════════════════════════

M=$(printf '\033[1;35m')
R=$(printf '\033[1;31m')
G=$(printf '\033[1;32m')
C=$(printf '\033[1;36m')
D=$(printf '\033[0;90m')
N=$(printf '\033[0m')

printf '%s  >> DEVINE Protected%s\n' "$M" "$N"

PMODE="DVXOR"
SALT="c57a27787ae31ded7bdc7b007042f415"

# Re-derive embedded key
EMBKEY=$(printf 'DEVINE::%s::SEED' "$SALT" | md5sum 2>/dev/null | awk '{print $1}')
[ -z "$EMBKEY" ] && EMBKEY=$(printf 'DEVINE::%s::SEED' "$SALT" | cksum | awk '{print $1}')

PAYLOAD="$(cat << 'PEOF'

PEOF
)"

TMP="/data/local/tmp/.dr_$$.sh"

case "$PMODE" in
    AES256)
        BIN="/data/local/tmp/.db_$$"
        printf '%s' "$PAYLOAD" | base64 -d > "$BIN" 2>/dev/null

        OS=""
        if command -v openssl >/dev/null 2>&1; then OS="openssl"
        elif command -v busybox >/dev/null 2>&1 && busybox openssl version >/dev/null 2>&1; then OS="busybox openssl"
        elif [ -x /data/local/tmp/openssl ]; then OS="/data/local/tmp/openssl"
        fi

        if [ -z "$OS" ]; then
            printf '%s  [X] OpenSSL missing.%s\n' "$R" "$N"
            rm -f "$BIN"; exit 1
        fi

        $OS enc -d -aes-256-cbc -pbkdf2 -iter 10000 -salt \
            -in "$BIN" -out "$TMP" -pass "pass:$EMBKEY" 2>/dev/null
        rm -f "$BIN"
        ;;

    DVXOR)
        HEXF="/data/local/tmp/.dh_$$"
        printf '%s' "$PAYLOAD" > "$HEXF"

        awk -v key="$EMBKEY" '
        BEGIN { klen=length(key); if(klen==0)klen=1; pos=0 }
        {
            hex=$0; hlen=length(hex)
            for(i=1;i<=hlen;i+=2){
                byte=substr(hex,i,2)
                bv=(index("0123456789abcdef",substr(byte,1,1))-1)*16
                bv+=(index("0123456789abcdef",substr(byte,2,1))-1)
                kc=substr(key,(pos%klen)+1,1)
                kb=ord(kc)
                sh=pos%13
                kb2=(kb+sh)%256
                tmp=(bv-sh+256)%256
                xb=xor(tmp,kb2)
                printf "%c",xb
                pos++
            }
        }
        function ord(ch,   i,map){
            map="0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!\"#$%&'"'"'()*+,-./:;<=>?@[\\]^_`{|}~ \t"
            i=index(map,ch); return (i>0)?i-1:0
        }
        function xor(a,b,   r,i,ab,bb){
            r=0; for(i=0;i<8;i++){ab=int(a/2^i)%2;bb=int(b/2^i)%2;if(ab!=bb)r+=2^i} return r
        }
        ' "$HEXF" > "$TMP" 2>/dev/null
        rm -f "$HEXF"
        ;;

    SIMPLE|*)
        printf '%s' "$PAYLOAD" | rev | base64 -d > "$TMP" 2>/dev/null
        ;;
esac

if [ ! -s "$TMP" ]; then
    printf '%s  [X] Decrypt fail.%s\n' "$R" "$N"
    rm -f "$TMP"; exit 1
fi

chmod +x "$TMP"
sh "$TMP" "$@"
RET=$?
rm -f "$TMP"
exit $RET
